mapper.select:
SELECT a.*, e.name as employee_name
FROM attendance_record a
LEFT JOIN sys_employee e ON a.employee_id = e.id
WHERE a.deleted = 0

    AND a.employee_id = #{query.employeeId}


    AND a.attendance_date >= #{query.startDate}


    AND a.attendance_date <= #{query.endDate}


    AND a.status = #{query.status}

ORDER BY a.attendance_date DESC, a.create_time DESC

SELECT COUNT(1) as total, COALESCE(SUM(CASE WHEN status = 'normal' THEN 1 ELSE 0 END), 0) as normal, COALESCE(SUM(CASE WHEN status = 'late' THEN 1 ELSE 0 END), 0) as late, COALESCE(SUM(CASE WHEN status = 'early' THEN 1 ELSE 0 END), 0) as early, COALESCE(SUM(CASE WHEN status = 'absent' THEN 1 ELSE 0 END), 0) as absent, COALESCE(SUM(CASE WHEN status = 'leave' THEN 1 ELSE 0 END), 0) as `leave`, COALESCE(SUM(CASE WHEN status = 'overtime' THEN 1 ELSE 0 END), 0) as overtime FROM attendance_record WHERE deleted = 0
AND attendance_date >= #{startDate}
AND attendance_date <= #{endDate}
